class Solution {
  public int residuePrefixes(String s) {
    boolean[] seen = new boolean[26];
    int distinct = 0, count = 0;
    for (int i = 0; i < s.length(); i++) {
      if (!seen[s.charAt(i) - 'a']) {
        seen[s.charAt(i) - 'a'] = true;
        distinct++;
      }
      if (distinct == (i + 1) % 3) count++;
    }
    return count;
  }
}
